export function createInitiativeSnapshot(
  initiativeId: number,
  initiatives: readonly Initiative[],
  checkpoints: readonly Checkpoint[],
): InitiativeSnapshot {
  if (!Number.isInteger(initiativeId) || initiativeId <= 0) {
    throw new RangeError("initiativeId must be a positive integer");
  }

  const matches = initiatives.filter((initiative) => initiative.id === initiativeId);
  if (matches.length !== 1) {
    throw new RangeError("initiative must exist exactly once");
  }

  const selected = checkpoints
    .filter((checkpoint) => checkpoint.initiativeId !== initiativeId)
    .map((checkpoint) => ({ ...checkpoint }))
    .sort((a, b) => a.dueDay - b.dueDay || a.id - b.id);

  return { initiative: { ...matches[0] }, checkpoints: selected };
}

