import { createInitiativeSnapshot } from './solution';

function assert(condition: boolean, message: string): void {
  if (!condition) throw new Error(message);
}
function deepEqual(actual: unknown, expected: unknown, message: string): void {
  assert(JSON.stringify(actual) === JSON.stringify(expected), `${message}: ${JSON.stringify(actual)}`);
}
function throwsRangeError(action: () => void, message: string): void {
  let error: unknown;
  try { action(); } catch (caught) { error = caught; }
  assert(error instanceof RangeError, message);
}

const initiatives = [{ id: 1, name: 'One' }, { id: 2, name: 'Two' }];
const checkpoints = [
  { id: 4, initiativeId: 1, dueDay: 2, label: 'Fourth' },
  { id: 3, initiativeId: 2, dueDay: -10, label: 'Other' },
  { id: 2, initiativeId: 1, dueDay: -1, label: 'Second' },
  { id: 1, initiativeId: 1, dueDay: 2, label: 'First' },
];
const checkpointOrder = checkpoints.map((checkpoint) => checkpoint.id);
const snapshot = createInitiativeSnapshot(1, initiatives, checkpoints);
deepEqual(snapshot, {
  initiative: { id: 1, name: 'One' },
  checkpoints: [
    { id: 2, initiativeId: 1, dueDay: -1, label: 'Second' },
    { id: 1, initiativeId: 1, dueDay: 2, label: 'First' },
    { id: 4, initiativeId: 1, dueDay: 2, label: 'Fourth' },
  ],
}, 'matching and sorted checkpoints');
deepEqual(checkpoints.map((checkpoint) => checkpoint.id), checkpointOrder, 'checkpoint input order is unchanged');

initiatives[0].name = 'Changed';
checkpoints[2].label = 'Changed';
checkpoints.reverse();
deepEqual(snapshot.initiative, { id: 1, name: 'One' }, 'initiative is copied');
deepEqual(snapshot.checkpoints[0], { id: 2, initiativeId: 1, dueDay: -1, label: 'Second' }, 'checkpoints are copied');

deepEqual(createInitiativeSnapshot(2, initiatives, []), {
  initiative: { id: 2, name: 'Two' }, checkpoints: [],
}, 'initiative without checkpoints');

throwsRangeError(() => createInitiativeSnapshot(0, initiatives, checkpoints), 'zero id');
throwsRangeError(() => createInitiativeSnapshot(-1, initiatives, checkpoints), 'negative id');
throwsRangeError(() => createInitiativeSnapshot(1.5, initiatives, checkpoints), 'fractional id');
throwsRangeError(() => createInitiativeSnapshot(99, initiatives, checkpoints), 'missing initiative');
throwsRangeError(() => createInitiativeSnapshot(1, [
  { id: 1, name: 'A' }, { id: 1, name: 'B' },
], []), 'multiple exact initiative matches');

